                  });
                })
              }

{() =>
                void run(async () => {
                  await calendarRequest("retry", businessId, "POST", {
                    integrationId: integration.id,
                  });
                })
              }

{() =>
                void run(async () => {
                  await calendarRequest("disconnect", businessId, "DELETE", {
                    integrationId: integration.id,
                    forget: true,
                  });
                })
              }

{(e) =>
                    setValue({
                      ...value,
                      payment_links: e.target.checked
                        ? [...value.payment_links, { provider: p.id, url: "" }]
                        : value.payment_links.filter(
                            (l) => l.provider !== p.id,
                          ),
                    })
                  }

{(e) =>
                      setValue({
                        ...value,
                        payment_links: value.payment_links.map((l) =>
                          l.provider === p.id
                            ? { ...l, url: e.target.value.trim() }
                            : l,
                        ),
                      })
                    }

{(e) =>
                setEditing({
                  ...editing,
                  role: e.target.value,
                  access_modules:
                    e.target.value === "office"
                      ? editing.access_modules
                      : editing.access_modules.filter(
                          (x) => !["billing", "finances"].includes(x),
                        ),
                })
              }

{async () => {
                    setBusy(true);
                    setError("");
                    try {
                      const r = await inviteMember(
                        business.id,
                        i.email,
                        i.role,
                        i.access_modules,
                        i.id,
                      );
                      setInviteUrl(r.url);
                      setNotice(
                        r.email_status === "accepted"
                          ? "New invitation email accepted. The previous link is no longer valid."
                          : "New link created. Email delivery is unconfirmed; copy the link to share it.",
                      );
                      await refresh();
                    } catch (e) {
                      setError(errorText(e));
                    } finally {
                      setBusy(false);
                    }
                  }}
